import express from "express";
import multer from "multer";
import statementController from "../controller/statement";

const statementsRouter = express.Router();

// Configure multer for file upload handling
const storage = multer.memoryStorage(); // Store files in memory for AI processing

const upload = multer({
  storage: storage,
  limits: {
    fileSize: 10 * 1024 * 1024, // 10MB limit
  },
  fileFilter: (req, file, cb) => {
    const allowedTypes = [
      "application/pdf",
      "image/jpeg",
      "image/jpg",
      "image/png",
    ];
    if (allowedTypes.includes(file.mimetype)) {
      cb(null, true);
    } else {
      cb(new Error("Invalid file type. Only PDF and images are allowed."));
    }
  },
});

// Routes
// POST /api/statements - Upload and process a new statement
statementsRouter.post(
  "/",
  upload.single("statement"),
  statementController.uploadStatement.bind(statementController)
);

// GET /api/statements - Get all statements for the authenticated user
statementsRouter.get("/", statementController.getStatements.bind(statementController));

// GET /api/statements/:id - Get a specific statement by ID
statementsRouter.get("/:id", statementController.getStatementById.bind(statementController));

// DELETE /api/statements/:id - Delete a statement
statementsRouter.delete("/:id", statementController.deleteStatement.bind(statementController));

export default statementsRouter;